mapper.select:
select * from (
    select sm.ID, sm.STEEL_RING_CODE, sm.MACHINE_CODE, sm.LINE_TYPE, sm.JOB_TYPE,
           sm.REMARK, sm.IS_DELETE, sm.CREATE_BY, sm.CREATE_TIME,
           sm.UPDATE_BY, sm.UPDATE_TIME,
           mi.MACHINE_NAME
    from T_GSQ_SPECIFY_MACHINE sm
    left join T_GSQ_MACHINE_INFO mi on sm.MACHINE_CODE = mi.MACHINE_CODE
        and mi.IS_DELETE = '0'
    where sm.IS_DELETE = '0'

        and sm.STEEL_RING_CODE = #{steelRingCode}


        and sm.MACHINE_CODE = #{machineCode}


        and sm.LINE_TYPE = #{lineType}


        and sm.JOB_TYPE = #{jobType}

    order by sm.STEEL_RING_CODE, mi.MACHINE_NAME
) t

SELECT count(1)
FROM T_GSQ_SPECIFY_MACHINE
where IS_DELETE = '0'
and STEEL_RING_CODE = #{steelRingCode}
and MACHINE_CODE = #{machineCode}
and ID != #{id}
